    var engBub = { text: '', tx: 0, ty: 0, a: 0, want: false }, engGen = 0, engDoor = null, engDoorOpen = -1, engSignIdx = {}, engArena = null, engDeadGone = false, engQuiet = false, engDarkCv = null, engSignAt = -1;
