        for (p = y + 1; p < y + h; p += 3) U.fill(g, 0, p, w, 1, '#0e1016');   // scan lines, barely there
        if (h < 200) { U.fill(g, 0, y, w, 1, '#f6efe2'); U.fill(g, 0, y + h - 1, w, 1, '#f6efe2'); return false; }
        return true;
