        for (i = 0; i < BEASTS[w].length; i++) { k = BEASTS[w][i]; d = Q.ENEMY[k]; out.push({ id: k, name: d && d.name ? String(d.name) : k.toUpperCase(), line: '', boss: !!(d && d.boss) }); }
