        S: ['.#####', '##....', '##....', '.####.', '....##', '....##', '#####.'],
        H: ['##..##', '##..##', '##..##', '######', '##..##', '##..##', '##..##'],
        D: ['#####.', '##..##', '##..##', '##..##', '##..##', '##..##', '#####.'],
        K: ['##..##', '##.##.', '####..', '###...', '####..', '##.##.', '##..##'],
        F: ['######', '##....', '##....', '#####.', '##....', '##....', '##....'],
        I: ['######', '..##..', '..##..', '..##..', '..##..', '..##..', '######'],
        V: ['##..##', '##..##', '##..##', '##..##', '##..##', '.####.', '..##..'],
        L: ['##....', '##....', '##....', '##....', '##....', '##....', '######'],
        R: ['#####.', '##..##', '##..##', '#####.', '####..', '##.##.', '##..##'],
        C: ['.#####', '##....', '##....', '##....', '##....', '##....', '.#####'],   // version 116: ENCORE
        ' ': ['......', '......', '......', '......', '......', '......', '......']
