      led: '#39e27a', ledHi: '#b8ffd2', ledDim: '#1e7a45', amber: '#ffb02e', red: '#ff4d4d', blue: '#5aa9ff',
      cab: '#ff8a1e', cabD: '#b45a10', cabL: '#ffb866', cabDD: '#6e3609',
