          if (Math.floor(e.stT * 20) % 4 === 0) Q.fx('spark', e.x + 2, e.y + 3 + Math.floor(e.stT * 37) % 9, { n: 1, col: '#ff8a1e' });
          if (e.stT >= D.tg) { e.st = 'blast'; Q.sfx('fan'); Q.shake(1.5, D.tb); B.data.heat = Math.min(100, B.data.heat + 4); }
