      k: '#1d1d24', w: '#ffffff', c: '#e3f0fb', s: '#bcd6ee', d: '#8fb2d8', b: '#5b7fb0', n: '#2f7de1', t: '#2ec4b6', u: '#1d8f86',
      y: '#ffd23f', o: '#ff8a1e', r: '#e2504c', l: '#a8dcf8', g: '#8a96a8', e: '#4a5670', p: '#c9b6f2', q: '#8f78d8', m: '#f2c14e'
