        if (what === 'REMATCH') { st = BT.setupNow(); st.arena = RE.setup ? RE.setup.arena : st.arena; st.slots = RE.setup ? RE.setup.slots : st.slots; Q.go('battle', { setup: st }); }
        else if (what === 'NEW ARENA') { Q.music('map'); Q.go('barena'); }
