          if (M) { for (i = 0; i < M.cs.length; i++) RE.order.push(M.cs[i]); RE.order.sort(function (a, b) { return M.wins[b.i] - M.wins[a.i] || M.stats[b.i].kos - M.stats[a.i].kos || a.i - b.i; }); }
