          x = 96; cl = [['WINS', 110], ['KOS', 138], ['FALLS', 168], ['HITS', 201]]; for (i = 0; i < cl.length; i++) U.text(cl[i][0], x + cl[i][1] - (U.width(cl[i][0]) >> 1), 32, '#8f9ac8');
